  function applyMenuBg() {
    const bg = document.querySelector(".menuBg:not(.menuBgFx)");
    const menu = $("menu");
    const col = colorOf(picked);
    if (menu) {
      menu.style.setProperty("--fac", col.primary);
      menu.style.setProperty("--fac2", col.accent);
    }
    if (!bg) return;
    const fac = String(picked).toLowerCase();
    const imgEl = document.getElementById("menuBgImg");
    const vidEl = document.getElementById("menuBgVideo");
    const tryBg = (urls, isVideo, cb) => {
      if (!urls.length) return cb(false);
      const url = urls[0];
      if (isVideo && vidEl) {
        const v = document.createElement("video");
        v.muted = true;
        v.loop = true;
        v.playsInline = true;
        v.oncanplay = () => {
          cb(true);
        };
        v.onerror = () => {
          tryBg(urls.slice(1), isVideo, cb);
        };
        v.src = url;
        window.setTimeout(() => {
          if (v.readyState < 2) tryBg(urls.slice(1), isVideo, cb);
        }, 900);
      } else {
        const probe = new Image();
        probe.onload = () => cb(true);
        probe.onerror = () => tryBg(urls.slice(1), isVideo, cb);
        probe.src = url;
      }
    };
    const imgUrls = [`/bg/menu/menu_${fac}`, `/bg/menu/menu`, `img/menu_${fac}.jpg`];
    const vidUrls = [`/bg/animated/menu/menu_${fac}`, `/bg/animated/menu/menu`, `/bg/menu/menu_${fac}`, `/bg/menu/menu`];
    tryBg(vidUrls, true, (okVideo) => {
      if (okVideo && vidEl) {
        const vSrc = vidUrls.find((u) => {
          return true;
        });
      }
    });
    const loadImgBg = (idx) => {
      if (idx >= imgUrls.length) {
        if (imgEl) {
          imgEl.classList.remove("show");
          imgEl.style.opacity = "0";
        }
        bg.style.backgroundImage = "";
        bg.classList.remove("hasCustomBg");
        loadVidBg(0);
        return;
      }
      const url = imgUrls[idx];
      const probe = new Image();
      probe.onload = () => {
        if (imgEl) {
          imgEl.src = url;
          imgEl.classList.add("show");
          imgEl.style.opacity = "1";
          imgEl.style.display = "block";
        }
        bg.classList.add("hasCustomBg");
        if (vidEl) {
          vidEl.classList.remove("show");
          vidEl.style.display = "none";
          vidEl.pause();
        }
        let fx = $("menuBgFx");
        if (!fx) {
          fx = el("div", "menuBg menuBgFx");
          fx.id = "menuBgFx";
          bg.parentElement?.insertBefore(fx, bg.nextSibling);
        }
        fx.style.backgroundImage = `url('${url}')`;
        void fx.offsetWidth;
        fx.classList.add("show");
        window.setTimeout(() => {
          bg.style.backgroundImage = `url('${url}')`;
          fx?.classList.remove("show");
        }, 560);
      };
      probe.onerror = () => loadImgBg(idx + 1);
      probe.src = url;
    };
    const loadVidBg = (idx) => {
      if (!vidEl || idx >= vidUrls.length) return;
      const url = vidUrls[idx];
      const test = document.createElement("video");
      test.muted = true;
      test.oncanplay = () => {
        vidEl.src = url;
        vidEl.style.display = "block";
        vidEl.classList.add("show");
        vidEl.style.opacity = "0.92";
        vidEl.play().catch(() => {
        });
        bg.classList.add("hasCustomBg");
        if (imgEl) {
          imgEl.classList.remove("show");
          imgEl.style.opacity = "0";
        }
      };
      test.onerror = () => loadVidBg(idx + 1);
      test.src = url;
      window.setTimeout(() => {
        if (test.readyState < 2) loadVidBg(idx + 1);
      }, 800);
    };
    loadImgBg(0);
  }
